xpath.script:
window.MathJax = window.MathJax || {
    tex: {
        inlineMath: [['$', '$'], ['\\(', '\\)']],
        displayMath: [['$$', '$$'], ['\\[', '\\]']],
        processEscapes: true
    },
    svg: { fontCache: 'global' },
    options: { skipHtmlTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code'] }
};

// Survey navigates between pages via AJAX (no full reload), so
// re-typeset whenever the question container is replaced.
document.addEventListener('DOMContentLoaded', function () {
    var root = document.querySelector('.o_survey_form');
    if (!root || !window.MutationObserver) return;
    var pending;
    new MutationObserver(function () {
        clearTimeout(pending);
        pending = setTimeout(function () {
            if (window.MathJax && window.MathJax.typesetPromise) {
                window.MathJax.typesetPromise([root]).catch(function () {});
            }
        }, 150);
    }).observe(root, { childList: true, subtree: true });
});

div.script:
window.MathJax = {
    tex: {
        inlineMath: [['$', '$'], ['\\(', '\\)']],
        displayMath: [['$$', '$$'], ['\\[', '\\]']],
        processEscapes: true,
        processEnvironments: true
    },
    svg: { fontCache: 'global', scale: 1 }
};
